INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3001, 'Leviticus 13:55', 'Leviticus', 13, 55, '&nbsp;بيا به هغه دا وګورى او کۀ پشم خپل رنګ نۀ وى بدل کړے او خور شوے هم نۀ وى، دا بيا هم ناپاک دے، خرابتيا کۀ د دې مخې ته وى يا شا ته وى تاسو هغه څيز وسوزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3002, 'Leviticus 13:56', 'Leviticus', 13, 56, '&nbsp;خو چې بيا يې وګورى، چې پشم اوچ شوے وى، نو هغه دې د هغه کپړې يا څرمنې نه خرابه شوې حِصه وشلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3003, 'Leviticus 13:57', 'Leviticus', 13, 57, '&nbsp;کۀ پشم بيا راڅرګند شى او خوريږى، نو د دې مالِک به دا څيز وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3004, 'Leviticus 13:58', 'Leviticus', 13, 58, '&nbsp;کۀ هغه دا څيز ووينځى او داغونه ورک شى، هغه به دا بيا ووينځى او دا به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3005, 'Leviticus 13:59', 'Leviticus', 13, 59, '&nbsp;نو دا قانون په کپړه د پشم په حقله دے، کۀ هغه پشم په وړۍ يا په لټه وى، يا د لټې يا د وړۍ په کپړه وى، يا د څرمنې جوړ شوى څيز باندې وى، نو د دې په بنياد به فېصله کولے شى چې دا پاک دى او کۀ ناپاک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3006, 'Leviticus 14:1', 'Leviticus', 14, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3007, 'Leviticus 14:2', 'Leviticus', 14, 2, '&nbsp;دا اصُول د هغه کس د پاکوالى دپاره دى چې د جذام د بيمارۍ نه روغ شوے وى. چې په کومه ورځ اِعلان وشى چې هغه پاک دے، نو هغه به اِمام له بوتلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3008, 'Leviticus 14:3', 'Leviticus', 14, 3, '&nbsp;او اِمام به هغه د خېمو نه بهر بوځى او وبه يې ګورى. کۀ هغه کس روغ شوے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3009, 'Leviticus 14:4', 'Leviticus', 14, 4, '&nbsp;نو اِمام به حُکم وکړى چې دوه حلال مارغان دې د دِيار د لرګى د يوې ټُکړې سره، يو د تک سور تار او د وېلنى بوټى سره راوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3010, 'Leviticus 14:5', 'Leviticus', 14, 5, '&nbsp;بيا به اِمام حُکم وکړى چې يو مارغۀ دې د خاورې لوښى دپاسه حلال کړے شى چې د چينې تازه اوبۀ په کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3011, 'Leviticus 14:6', 'Leviticus', 14, 6, '&nbsp;هغه به ژوندے مارغۀ د دِيار د لرګى، د تک سور تار او د وېلنى سره، د هغۀ مارغۀ په وينه کښې ډُوب کړى کوم چې حلال شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3012, 'Leviticus 14:7', 'Leviticus', 14, 7, '&nbsp;هغه به اووۀ ځله هغه وينه په هغه سړى باندې وشيندى کوم چې د جذام د بيمارۍ نه پاکولے شى او بيا به هغه اِعلان وکړى چې دا کس پاک دے. هغه به ژوندے مارغۀ آزاد کړى چې په هوا کښې والوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3013, 'Leviticus 14:8', 'Leviticus', 14, 8, '&nbsp;هغه کس به خپلې جامې ووينځى، ټول وېښتۀ به کل کړى او غسل به وکړى، نو پاک به شى. بيا هغه خېمو ته تلے شى، خو هغه به اووۀ ورځې د خپلې خېمې نه بهر اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3014, 'Leviticus 14:9', 'Leviticus', 14, 9, '&nbsp;په اوومه ورځ به هغه بيا خپل سر، ږيره، وروځې او د بدن نور ټول وېښتۀ کل کړى، هغه به خپلې جامې ووينځى او غسل به وکړى، نو هغه به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3015, 'Leviticus 14:10', 'Leviticus', 14, 10, '&nbsp;په اتمه ورځ به هغه دوه ګډُورى او يوه ګډورۍ چې د يو کال وى او هيڅ عېب په کښې نۀ وى، درې کلو اوړۀ چې د زيتُونو تېل ورسره ګډ وى او د ليټر درېمه حِصه د زيتُونو تېل دې راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3016, 'Leviticus 14:11', 'Leviticus', 14, 11, '&nbsp;اِمام به هغه کس او دا نذرانې د مالِک خُدائ د حضور مقدسې خېمې د دروازې خولې ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3017, 'Leviticus 14:12', 'Leviticus', 14, 12, '&nbsp;بيا به اِمام يو ګډُورے او د تېلو د ليټر درېمه حِصه يوسى او دا به د ګناه د تاوان د نذرانې په توګه پېش کړى. هغه به دا د اِمام دپاره مالِک خُدائ ته د خاص نذرانې په توګه پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3018, 'Leviticus 14:13', 'Leviticus', 14, 13, '&nbsp;هغه به ګډُورے په هغه مقدس ځائ کښې حلال کړى چرته چې د ګناه نذرانې او د سوزېدونکې نذرانې دپاره ځناور حلالولے شى. دا ځکه چې د ګناه د تاوان نذرانه، د ګناه د نذرانې په شان د اِمام ده او ډېره مقدسه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3019, 'Leviticus 14:14', 'Leviticus', 14, 14, '&nbsp;اِمام به د ګډُورى لږه وينه واخلى او د هغه کس د ښى غوږ په نرم ځائ پورې، د هغۀ د ښى لاس په غټې ګوتې پورې او د هغۀ د ښۍ پښې په غټې ګوتې پورې دې ولګوى د کوم کس چې اِعلان کيږى چې دا پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3020, 'Leviticus 14:15', 'Leviticus', 14, 15, '&nbsp;اِمام به د زيتُونو لږ تېل واخلى او د خپل ګس لاس په تلى کښې به يې واچوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3021, 'Leviticus 14:16', 'Leviticus', 14, 16, '&nbsp;د خپل ښى لاس ګوته به په دې کښې ډُوبه کړى او لږ به هلته د مالِک خُدائ په حضور کښې اووۀ ځله وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3022, 'Leviticus 14:17', 'Leviticus', 14, 17, '&nbsp;هغه به څۀ تېل چې د هغۀ د لاس په تلى کښې دى او څۀ د ګډُورى وينه واخلى او د هغه کس د ښى غوږ په نرم ځائ پورې، د هغۀ د ښى لاس په غټې ګوتې پورې او د هغۀ د ښۍ پښې په غټې ګوتې پورې ولګوى چې د کوم کس اِعلان کيږى چې دا پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3023, 'Leviticus 14:18', 'Leviticus', 14, 18, '&nbsp;د هغۀ د لاس په تلى کښې چې کوم پاتې شوى تېل دى هغه به د دې کس په سر باندې ولګوى. نو د هغۀ د پاکوالى کفاره به ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3024, 'Leviticus 14:19', 'Leviticus', 14, 19, '&nbsp;بيا به اِمام د ګناه نذرانه پېش کړى او د پاکوالى کفاره به ادا کړى. د هغې نه پس، هغه به د سوزېدونکې نذرانې دپاره ځناور حلال کړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3025, 'Leviticus 14:20', 'Leviticus', 14, 20, '&nbsp;او دا به د غلې نذرانې سره په قربان‌ګاه باندې پېش کړى. نو اِمام به د پاکوالى کفاره ادا کړى او هغه کس به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3026, 'Leviticus 14:21', 'Leviticus', 14, 21, '&nbsp;کۀ هغه غريب وى او نور څۀ نۀ شى اخستلے، نو د هغۀ د پاکوالى د کفارې ادا کولو دپاره دې هغه يو ګډُورے د ګناه د تاوان د نذرانې په توګه پېش کړى، دا به مالِک خُدائ ته د اِمام دپاره يوه خاص تُحفه وى. هغه به صِرف يو کلو اوړۀ چې د زيتُونو تېل ورسره ګډ وى، دا د غلې د نذرانې دپاره او د ليټر درېمه حِصه د زيتُونو تېل راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3027, 'Leviticus 14:22', 'Leviticus', 14, 22, '&nbsp;هغه به دوه ګوګوشتکې يا دوه کونترې هم راوړى، يوه د ګناه نذرانې دپاره او يوه به د سوزېدونکې نذرانې دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3028, 'Leviticus 14:23', 'Leviticus', 14, 23, '&nbsp;د هغۀ د پاکوالى په اتمه ورځ به هغه دا د مقدسې خېمې د دروازې په خولۀ کښې اِمامانو له راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3029, 'Leviticus 14:24', 'Leviticus', 14, 24, '&nbsp;اِمام به ګډُورے او د زيتُونو تېل واخلى او مالِک خُدائ ته به يې د يوې خاص تُحفې په توګه د اِمام دپاره پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3030, 'Leviticus 14:25', 'Leviticus', 14, 25, '&nbsp;هغه به ګډُورے حلال کړى او د دې څۀ وينه به واخلى او د هغه کس د ښى غوږ په نرم ځائ پورې، د ښى لاس په غټې ګوتې پورې او د هغۀ د ښۍ پښې په غټې ګوتې پورې ولګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3031, 'Leviticus 14:26', 'Leviticus', 14, 26, '&nbsp;اِمام به لږ تېل د خپل ګس لاس په تلى کښې واچوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3032, 'Leviticus 14:27', 'Leviticus', 14, 27, '&nbsp;او د خپل ښى لاس د يوې ګوتې سره به څۀ تېل د مالِک خُدائ په حضور کښې اووۀ ځله وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3033, 'Leviticus 14:28', 'Leviticus', 14, 28, '&nbsp;هغه به څۀ تېل هم په هغه ځايونو پورې ولګوى چې څنګه يې وينه لګولې وه، د هغۀ د ښى غوږ په نرم ځائ پورې، د هغۀ د ښى لاس په غټې ګوتې پورې، او د هغۀ د ښۍ پښې په غټې ګوتې پورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3034, 'Leviticus 14:29', 'Leviticus', 14, 29, '&nbsp;د هغۀ په تلى کښې چې کوم پاتې شوى تېل دى هغه دې د هغه کس په سر واچوى او داسې به د پاکوالى کفاره ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3035, 'Leviticus 14:30', 'Leviticus', 14, 30, '&nbsp;بيا به هغه يوه ګوګوشتکه يا کونتره پېش کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3036, 'Leviticus 14:31', 'Leviticus', 14, 31, '&nbsp;دا به د ګناه د نذرانې په توګه او هغه بله د غلې د نذرانې سره، د سوزېدونکې نذرانې په توګه پېش کړى. نو اِمام به د مالِک خُدائ په حضور کښې د هغه کس د پاکوالى کفاره ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3037, 'Leviticus 14:32', 'Leviticus', 14, 32, '&nbsp;دا قانون د هغه چا دپاره دے چې د جذام بيمارى لرى خو د خپل پاکوالى دپاره عامې نذرانې نۀ شى اخستلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3038, 'Leviticus 14:33', 'Leviticus', 14, 33, '&nbsp;بيا مالِک خُدائ موسىٰ او هارون ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3039, 'Leviticus 14:36', 'Leviticus', 14, 36, '&nbsp;نو چې کله اِمام پشم ليدلو له هلته ورځى نو هغه به حُکم وکړى چې هر څۀ دې د هغه کور نه بهر وويستلے شى، هسې نه چې د هغه کور ټول سامان ناپاکه اِعلان کړے شى. نو د دې نه وروسته دې اِمام کور ته ورشى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3040, 'Leviticus 14:37', 'Leviticus', 14, 37, '&nbsp;او پشم به وګورى. کۀ په دې کښې شين بخن يا سور بخن داغونه وى چې دېوال خرابوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3041, 'Leviticus 14:38', 'Leviticus', 14, 38, '&nbsp;اِمام به د هغه کور نه لاړ شى او اووۀ ورځې به يې بند وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3042, 'Leviticus 14:39', 'Leviticus', 14, 39, '&nbsp;په اوومه ورځ به هغه واپس راشى او بيا به يې وګورى. کۀ پشم خور شوے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3043, 'Leviticus 14:40', 'Leviticus', 14, 40, '&nbsp;هغه به حُکم وکړى چې هغه کاڼى دې لرې کړے شى چې په کومو باندې پشم ښکارى او د ښار نه بهر په يو ناپاک ځائ کښې دې وغورزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3044, 'Leviticus 14:41', 'Leviticus', 14, 41, '&nbsp;بيا دې هغه دننه ټول دېوالونه وتراشى او هغه راغورزېدلې خاوره دې د ښار نه بهر يو ناپاک ځائ ته يوړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3045, 'Leviticus 14:42', 'Leviticus', 14, 42, '&nbsp;چې کوم کاڼى لرې کړے شوى وى نو د هغې په ځائ دې نور استعمال کړے شى او دېوالونه دې په نوې خټه باندې لېو کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3046, 'Leviticus 14:43', 'Leviticus', 14, 43, '&nbsp;د کاڼو د لرې کولو او دېوالونو د تراشلو او لېولو نه پس کۀ بيا په هغه کور کښې پشم راښکاره شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3047, 'Leviticus 14:44', 'Leviticus', 14, 44, '&nbsp;نو اِمام به لاړ شى او وبه يې ګورى. کۀ پشم خور شوے وى، نو کور ناپاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3048, 'Leviticus 14:45', 'Leviticus', 14, 45, '&nbsp;هغه کور دې خامخا وران کړے شى او د دې کاڼى، لرګى او د دې ټولې خاورې دې د ښار نه بهر يو ناپاک ځائ ته يوړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3049, 'Leviticus 14:46', 'Leviticus', 14, 46, '&nbsp;هر څوک چې هغه کور ته دننه لاړ شى کله چې هغه تاله وى نو هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3050, 'Leviticus 14:47', 'Leviticus', 14, 47, '&nbsp;هر څوک چې په دې کور کښې څملى يا په کښې خوراک وکړى نو خامخا به خپلې جامې وينځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3051, 'Leviticus 14:48', 'Leviticus', 14, 48, '&nbsp;کۀ کله اِمام د دې کتلو له راشى او د کور د بيا لېولو نه پس پشم راڅرګند شوے نۀ وى، نو هغه به اِعلان وکړى چې کور پاک دے، ځکه چې پشم ورک شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3052, 'Leviticus 14:49', 'Leviticus', 14, 49, '&nbsp;د کور د پاکولو دپاره، هغه به دوه مارغان، د دِيار لرګے، يو تک سور تار او د وېلنى يوه څانګه واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3053, 'Leviticus 14:50', 'Leviticus', 14, 50, '&nbsp;هغه به يو مارغۀ د خټې يو لوښى دپاسه حلال کړى چې د چينې تازه اوبۀ په کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3054, 'Leviticus 14:51', 'Leviticus', 14, 51, '&nbsp;بيا به هغه د دِيار لرګے، د وېلنى څانګه، تک سور تار او هغه ژوندے مارغۀ واخلى او دا به د هغه حلال شوى مارغۀ په وينه کښې او په تازه اوبو کښې ډُوب کړى. او دا وينه او اوبۀ دې په کور باندې اووۀ ځله وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3055, 'Leviticus 14:52', 'Leviticus', 14, 52, '&nbsp;نو هغه به دا کور د مارغۀ د وينې په ذريعه، د تازه اوبو او ژوندى مارغۀ، د دِيار لرګى، د وېلنى او د سور تار سره پاک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3056, 'Leviticus 14:53', 'Leviticus', 14, 53, '&nbsp;بيا به هغه ژوندے مارغۀ آزاد کړى چې د ښار نه بهر په هوا کښې والوځى. نو داسې هغه به د کور د پاکوالى دپاره کفاره ادا کړى او دا به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3057, 'Leviticus 14:54', 'Leviticus', 14, 54, '&nbsp;دا قانون د جذام بيمارۍ او خارښت په حقله دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3058, 'Leviticus 14:57', 'Leviticus', 14, 57, '&nbsp;کۀ يو څيز پاک يا ناپاک وى نو په دې قانون به فېصله کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3059, 'Leviticus 15:1', 'Leviticus', 15, 1, '&nbsp;بيا مالِک خُدائ موسىٰ او هارون ته دا اصُول وښودل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3060, 'Leviticus 15:2', 'Leviticus', 15, 2, '&nbsp;کوم چې د بنى اِسرائيلو دپاره دى. کۀ د سړى د ذکر نه څۀ اوبۀ ووځى، نو هغه اوبۀ ناپاکې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3061, 'Leviticus 15:3', 'Leviticus', 15, 3, '&nbsp;کۀ د هغۀ د ذکر نه اوبۀ روانې وى يا بند وى نو هغه ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3062, 'Leviticus 15:4', 'Leviticus', 15, 4, '&nbsp;چې په کومه بستره هغه څملاستلے وى يا په بل څۀ باندې ناست وى نو هغه به هم ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3063, 'Leviticus 15:5', 'Leviticus', 15, 5, '&nbsp;هر څوک چې د هغۀ بسترې له لاس وروړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3064, 'Leviticus 15:6', 'Leviticus', 15, 6, '&nbsp;يا په هر څۀ باندې کښېنى په کوم باندې چې هغه سړے ناست وى نو هغه به جامې ووينځى او غسل به وکړى او تر ماښامه پورې به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3065, 'Leviticus 15:7', 'Leviticus', 15, 7, '&nbsp;کۀ څوک هغه سړى له لاس وروړى چې د کوم نه اوبۀ ځى نو هغه به خامخا خپلې جامې ووينځى او غسل به وکړى او تر ماښامه پورې به ناپاکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3066, 'Leviticus 15:8', 'Leviticus', 15, 8, '&nbsp;چې د کوم سړى د ذکر نه اوبۀ ځى کۀ هغه په يو پاک کس توکاڼې اوتُوکى، نو هغه کس به خامخا جامې ووينځى او غسل به وکړى او تر ماښامه پورې به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3067, 'Leviticus 15:9', 'Leviticus', 15, 9, '&nbsp;په کوم زين چې هغه سړے کښېنى چې د کوم سړى د ذکر نه چې اوبۀ ځى نو هغه زين به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3068, 'Leviticus 15:10', 'Leviticus', 15, 10, '&nbsp;هر څوک چې هر هغه څيز له ګوتې وروړى چې په کوم باندې هغه سړے ناست وى نو هغه به تر ماښامه پورې ناپاک وى. کۀ څوک هر هغه څيز يوسى چې په کوم باندې هغه سړے ناست وى نو هغه به خامخا خپلې جامې ووينځى او غسل به وکړى او تر ماښامه پورې به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3069, 'Leviticus 15:11', 'Leviticus', 15, 11, '&nbsp;د کوم سړى د ذکر نه چې اوبۀ ځى کۀ هغۀ خپل لاسونه نۀ وى وينځلى او چا له ګوتې وروړى، نو هغه کس به خامخا خپلې جامې ووينځى او غسل به وکړى، خو هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3070, 'Leviticus 15:12', 'Leviticus', 15, 12, '&nbsp;هغه سړے کۀ د خټو لوښى له لاس وروړى نو دا به ماتولے شى او کۀ د لرګى لوښى له لاس وروړى نو خامخا به وينځلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3071, 'Leviticus 15:13', 'Leviticus', 15, 13, '&nbsp;د کوم سړى چې د ذکر نه اوبۀ ځى او هغه روغ شى نو د هغې نه پس، هغه به خامخا اووۀ ورځې اِنتظار کوى او بيا به خپلې جامې ووينځى او د چينې په تازه اوبو کښې به غسل وکړى او هغه به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3072, 'Leviticus 15:14', 'Leviticus', 15, 14, '&nbsp;په اتمه ورځ به هغه دوه ګوګوشتکې يا دوه کونترې د مالِک خُدائ د حضور مقدسې خېمې د دروازې خولې ته يوسى او اِمام له به يې ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3073, 'Leviticus 15:15', 'Leviticus', 15, 15, '&nbsp;او اِمام به د دې نه يوه د ګناه د نذرانې په توګه او بله د سوزېدونکې نذرانې په توګه پېش کړى، چې د هغه سړى د پاکوالى کفاره ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3074, 'Leviticus 15:16', 'Leviticus', 15, 16, '&nbsp;کله چې د يو سړى نه منى ووځى، نو هغه به خامخا خپل ټول بدن ووينځى او هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3075, 'Leviticus 15:17', 'Leviticus', 15, 17, '&nbsp;هر څيز چې د کپړې يا څرمنې نه جوړ وى او منى ورباندې پرېوځى نو خامخا به وينځلے شى او تر ماښامه پورې به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3076, 'Leviticus 15:18', 'Leviticus', 15, 18, '&nbsp;د سړى او ښځې د کوروالى کولو نه پس به خامخا دواړه غسل کوى او هغوئ به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3077, 'Leviticus 15:19', 'Leviticus', 15, 19, '&nbsp;چې کله د يوې ښځې مياشتنۍ بيمارى وى، نو هغه به اووۀ ورځې ناپاکه وى. هر څوک چې هغې له لاس وروړى نو هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3078, 'Leviticus 15:20', 'Leviticus', 15, 20, '&nbsp;د مياشتنۍ بيمارۍ په دوران کښې چې هغه په هر څيز باندې کښېنى يا څملى نو دا به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3079, 'Leviticus 15:24', 'Leviticus', 15, 24, '&nbsp;کۀ يو سړے د هغې سره په داسې وخت کښې څملى چې مياشتنۍ بيمارى يې وى، نو هغه د هغې د ناپاکۍ په وجه ناپاک دے او اووۀ ورځې به ناپاک وى او هغه بستره هم ناپاکه ده په کومه باندې چې هغه څملى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3080, 'Leviticus 15:25', 'Leviticus', 15, 25, '&nbsp;کۀ د يوې ښځې د مياشتنۍ بيمارۍ نه بغېر هم د ډېرو ورځو پورې وينه بهيږى يا د مياشتنۍ بيمارۍ د ورځو نه اخوا هم د هغې نه وينه جارى وى، نو تر کومې پورې چې ترې نه وينه بهيږى هغه ناپاکه ده، لکه چې څنګه د مياشتنۍ بيمارۍ په وخت کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3081, 'Leviticus 15:26', 'Leviticus', 15, 26, '&nbsp;په دې دوران کښې چې هغه په کومه بستره څملى او په څۀ څيز باندې کښېنى نو دا ناپاک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3082, 'Leviticus 15:27', 'Leviticus', 15, 27, '&nbsp;هر څوک چې دې څيزونو له لاس وروړى نو هغه ناپاک دے او خامخا به خپلې جامې ووينځى او غسل به وکړى، هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3083, 'Leviticus 15:28', 'Leviticus', 15, 28, '&nbsp;چې د هغې نه وينه بهېدل بند شى نو هغه به خامخا اووۀ ورځې اِنتظار کوى او بيا به هغه پاکه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3084, 'Leviticus 15:29', 'Leviticus', 15, 29, '&nbsp;په اتمه ورځ به هغه دوه ګوګوشتکې يا دوه کونترې د مالِک خُدائ د مقدسې خېمې د دروازې په خولۀ کښې اِمام له يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3085, 'Leviticus 15:30', 'Leviticus', 15, 30, '&nbsp;اِمام به د دې نه يوه د ګناه د نذرانې په توګه او بله د سوزېدونکې نذرانې په توګه پېش کړى، نو د هغې دپاره به د پاکوالى کفاره ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3086, 'Leviticus 15:31', 'Leviticus', 15, 31, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل چې بنى اِسرائيلو له خبردارے ورکړه چې څوک ناپاک وى هغه به لرې اوسيږى، نو د مالِک خُدائ د حضور مقدسې خېمې بې‌عزتى به نۀ کيږى، کومه چې د خېمو په مينځ کښې ده. کۀ هغوئ بې‌عزتى وکړه، نو مړۀ به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3087, 'Leviticus 15:32', 'Leviticus', 15, 32, '&nbsp;دا اصُول د هغه سړى په حقله دى چې د ذکر نه يې اوبۀ يا منى ځى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3088, 'Leviticus 15:33', 'Leviticus', 15, 33, '&nbsp;دا د داسې ښځې په حقله دى چې د هغې مياشتنۍ بيمارى وى، يا د يو سړى په حقله چې د يوې ښځې سره څملى کومه چې ناپاکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3089, 'Leviticus 16:1', 'Leviticus', 16, 1, '&nbsp;مالِک خُدائ موسىٰ ته د هارون د دوو زامنو د مرګ نه پس وفرمائيل چې کله هغوئ مالِک خُدائ ته هغه اور پېش کړو کوم چې خُدائ پاک ته قبول نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3090, 'Leviticus 16:2', 'Leviticus', 16, 2, '&nbsp;مالِک خُدائ وفرمائيل، ”خپل ورور هارون ته ووايه چې هغه به صِرف په مناسب وخت د پړدې شا ته زيات مقدس ځائ ته ننوځى، ځکه چې زۀ به هلته په وريځ کښې د لوظ صندوق د کفارې تخت دپاسه راښکاره کېږم. کۀ هغۀ نافرمانى وکړه، نو هغه به ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3091, 'Leviticus 16:3', 'Leviticus', 16, 3, '&nbsp;هغه زيات مقدس ځائ ته د هغې نه پس داخلېدلے شى چې يو سخے د ګناه د نذرانې دپاره او يو ګډ د سوزېدونکې نذرانې دپاره راولى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3092, 'Leviticus 16:4', 'Leviticus', 16, 4, '&nbsp;بيا مالِک خُدائ دا اصُول وښودل. زيات مقدس ځائ ته ننوتلو نه مخکښې دې هارون خامخا غسل وکړى او د اِمامانو لِباس دې واغوندى، د کتان چُوغه او جانګى، پټۍ او پټکے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3093, 'Leviticus 16:5', 'Leviticus', 16, 5, '&nbsp;د بنى اِسرائيلو قوم به هارون له د ګناه د نذرانې دپاره دوه چېلى او يو ګډ د سوزېدونکې نذرانې دپاره ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3094, 'Leviticus 16:6', 'Leviticus', 16, 6, '&nbsp;هغه به يو غوَيے د نذرانې په توګه پېش کړى چې د هغۀ د خپلې ګناه او د هغۀ د خاندان کفاره ادا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3095, 'Leviticus 16:7', 'Leviticus', 16, 7, '&nbsp;بيا به هغه دوه چېلى د مالِک خُدائ د مقدسې خېمې د دروازې خولې ته بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3096, 'Leviticus 16:8', 'Leviticus', 16, 8, '&nbsp;هلته به هغه پچه واچوى، دوه تيږې به راواخلى، په يوه باندې به ”مالِک خُدائ دپاره“ نښه واچوى او په بله به ”عزازيل دپاره“ نښه واچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3097, 'Leviticus 16:9', 'Leviticus', 16, 9, '&nbsp;هارون به هغه چېلے حلال کړى چې د مالِک خُدائ دپاره د پچې په ذريعه خوښ کړے شوے وى او د ګناه د نذرانې په توګه به يې پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3098, 'Leviticus 16:10', 'Leviticus', 16, 10, '&nbsp;چې کوم چېلے د عزازيل دپاره خوښ کړے شوے وى هغه به مالِک خُدائ ته ژوندے پېش کيږى او په بيابان کښې به عزازيل ته وشړلے شى، چې د خلقو د ګناه کفاره ادا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3099, 'Leviticus 16:11', 'Leviticus', 16, 11, '&nbsp;چې کله هارون غوَيے د خپلې ګناه او د خپل خاندان د ګناه دپاره د نذرانې په توګه قربانى کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3100, 'Leviticus 16:12', 'Leviticus', 16, 12, '&nbsp;هغه به دوه موټى ښه خوشبوئى او د قربان‌ګاه نه يو مجمر د بلو سکارو واخلى او زيات مقدس ځائ ته به يې دننه راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');